window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1eb3bd252b994061"]={"versions": [{"id": "FIG-1eb3bd252b994061", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozess- und Werkzeugkopplungsdiagramm (Tool Interoperability Workflow) im Kontext der AUTOSAR-Methodik. Das Diagramm illustriert das Zusammenspiel zwischen AUTOSAR-Authoring-Werkzeugen und externen Verhaltensmodellierungswerkzeugen (Behavioral Modeling Tools, BMT) über ein Kopplungswerkzeug (Coupling Tool) sowie den Austausch relevanter AUTOSAR-XML-Beschreibungsdateien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Werkzeuge (Tooling / Tool Role Symbol):</strong></li>\n<li><code>Coupling Tool</code>: Vermittelt zwischen AUTOSAR-SW-C-Beschreibung und externem Verhaltensmodell.</li>\n<li><code>Authoring tool for editing the SWC Description</code> (angeschnitten unten links): Werkzeug für Software-Komponenten-Definition.</li>\n<li><code>Authoring tool for editing the System Description</code> (angeschnitten unten Mitte): Werkzeug für Deployment und Systembeschreibung.</li>\n<li><code>Authoring Tool for editing the BSW Module</code> (angeschnitten unten rechts): Werkzeug für Basissoftware-Moduldefinition.</li>\n<li><strong>Artefakte / Datenmodelle:</strong></li>\n<li><code>Behavioral Model</code>: Externes Verhaltensmodell (Dokumentensymbol).</li>\n<li><code>.XML</code> <code>VFB Atomic Software Component</code>: AUTOSAR-XML-Beschreibung der atomaren SW-C.</li>\n<li><code>.XML</code> <code>System Description</code>: AUTOSAR-Systembeschreibung.</li>\n<li><code>.XML</code> <code>Basic Software Module Description</code>: AUTOSAR-BSW-Modulbeschreibung.</li>\n<li><strong>Aufgaben / Prozessschritte (als abgerundete Rechtecke bzw. Chevrons):</strong></li>\n<li>Innerhalb des Bereichs <code>Covered by AUTOSAR authoring tools</code>:</li>\n<li><code>Define VFB Application Software Component</code></li>\n<li><code>Deploy Software Component</code> (mit Verknüpfung zu einer Notiz: <em>„This task can be performed manually within an authoring tool. It is only an example of several tasks to be performed in order to modify/create a system description.“</em>)</li>\n<li><code>Define BSW Module Intefaces</code> [sic]</li>\n<li>Oberhalb / gekoppelt über <code>Coupling Tool</code>:</li>\n<li><code>Translation of SW-C Description into Behavioral Model</code> (Prozesspfeil)</li>\n<li><code>Translation of Behavioral Model into SW-C Description</code> (Prozesspfeil)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Definition der SW-C:</strong> Die Aufgabe <code>Define VFB Application Software Component</code> (unterstützt durch das entsprechende Authoring-Tool) erzeugt die <code>VFB Atomic Software Component</code> (.XML).</li>\n<li><strong>Kopplung an Verhaltensmodellierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die XML-Beschreibung wird via <code>Translation of SW-C Description into Behavioral Model</code> in ein <code>Behavioral Model</code> überführt.</li>\n<li>Das modifizierte oder erstellte <code>Behavioral Model</code> wird via <code>Translation of Behavioral Model into SW-C Description</code> zurück in die XML-SW-C-Beschreibung überführt.</li>\n<li>Beide Übersetzungsschritte sind dem <code>Coupling Tool</code> zugeordnet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Systemintegration und Deployment:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>VFB Atomic Software Component</code> fließt in den Schritt <code>Deploy Software Component</code> ein.</li>\n<li><code>Deploy Software Component</code> interagiert bidirektional mit der <code>System Description</code> (.XML) (Lesen/Modifizieren bzw. Erzeugen).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>BSW-Definition:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Define BSW Module Intefaces</code> interagiert bidirektional mit der <code>Basic Software Module Description</code> (.XML).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Konzeptionelle Darstellung zur werkzeuggestützten Interoperabilität gemäß AUTOSAR-Methodik.</li>\n<li>Das Diagramm verdeutlicht die Trennung zwischen struktureller AUTOSAR-Modellierung (SW-C-Beschreibung) und detailliertem Verhalten (Behavioral Model).</li>\n<li>Der rote Rahmen grenzt die Aufgaben ab, die typischerweise von AUTOSAR-Authoring-Tools abgedeckt werden, von den Aufgaben des externen Coupling Tools.</li>\n<li>Fehlerhafter Bezeichner <code>Intefaces</code> im Schritt <code>Define BSW Module Intefaces</code> ist als Schreibfehler im Standarddokument zu beachten.</li>\n</ul>"}, {"id": "FIG-9b7b3e1a46933b02", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozess- und Werkzeugkopplungsdiagramm (Tool Interoperability Workflow) im Kontext der AUTOSAR-Methodik. Das Diagramm illustriert das Zusammenspiel zwischen AUTOSAR-Authoring-Werkzeugen und externen Verhaltensmodellierungswerkzeugen (Behavioral Modeling Tools, BMT) über ein Kopplungswerkzeug (Coupling Tool) sowie den Austausch relevanter AUTOSAR-XML-Beschreibungsdateien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Werkzeuge (Tooling / Tool Role Symbol):</strong></li>\n<li><code>Coupling Tool</code>: Vermittelt zwischen AUTOSAR-SW-C-Beschreibung und externem Verhaltensmodell.</li>\n<li><code>Authoring tool for editing the SWC Description</code> (angeschnitten unten links): Werkzeug für Software-Komponenten-Definition.</li>\n<li><code>Authoring tool for editing the System Description</code> (angeschnitten unten Mitte): Werkzeug für Deployment und Systembeschreibung.</li>\n<li><code>Authoring Tool for editing the BSW Module</code> (angeschnitten unten rechts): Werkzeug für Basissoftware-Moduldefinition.</li>\n<li><strong>Artefakte / Datenmodelle:</strong></li>\n<li><code>Behavioral Model</code>: Externes Verhaltensmodell (Dokumentensymbol).</li>\n<li><code>.XML</code> <code>VFB Atomic Software Component</code>: AUTOSAR-XML-Beschreibung der atomaren SW-C.</li>\n<li><code>.XML</code> <code>System Description</code>: AUTOSAR-Systembeschreibung.</li>\n<li><code>.XML</code> <code>Basic Software Module Description</code>: AUTOSAR-BSW-Modulbeschreibung.</li>\n<li><strong>Aufgaben / Prozessschritte (durchgängig als Chevrons / Prozesspfeile dargestellt):</strong></li>\n<li>Innerhalb des Bereichs <code>Covered by AUTOSAR authoring tools</code>:</li>\n<li><code>Define VFB Application Software Component</code></li>\n<li><code>Deploy Software Component</code> (mit Verknüpfung zu einer Notiz: <em>„This task can be performed manually within an authoring tool. It is only an example of several tasks to be performed in order to modify/create a system description.“</em>)</li>\n<li><code>Define BSW Module Intefaces</code> [sic]</li>\n<li>Oberhalb / gekoppelt über <code>Coupling Tool</code>:</li>\n<li><code>Translation of SW-C Description into Behavioral Model</code></li>\n<li><code>Translation of Behavioral Model into SW-C Description</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Definition der SW-C:</strong> Die Aufgabe <code>Define VFB Application Software Component</code> (unterstützt durch das entsprechende Authoring-Tool) erzeugt die <code>VFB Atomic Software Component</code> (.XML).</li>\n<li><strong>Kopplung an Verhaltensmodellierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die XML-Beschreibung wird via <code>Translation of SW-C Description into Behavioral Model</code> in ein <code>Behavioral Model</code> überführt.</li>\n<li>Das modifizierte oder erstellte <code>Behavioral Model</code> wird via <code>Translation of Behavioral Model into SW-C Description</code> zurück in die XML-SW-C-Beschreibung überführt.</li>\n<li>Beide Übersetzungsschritte sind dem <code>Coupling Tool</code> zugeordnet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Systemintegration und Deployment:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>VFB Atomic Software Component</code> fließt in den Schritt <code>Deploy Software Component</code> ein.</li>\n<li><code>Deploy Software Component</code> interagiert bidirektional mit der <code>System Description</code> (.XML) (Lesen/Modifizieren bzw. Erzeugen).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>BSW-Definition:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Define BSW Module Intefaces</code> interagiert bidirektional mit der <code>Basic Software Module Description</code> (.XML).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Konzeptionelle Darstellung zur werkzeuggestützten Interoperabilität gemäß AUTOSAR-Methodik.</li>\n<li>Das Diagramm verdeutlicht die Trennung zwischen struktureller AUTOSAR-Modellierung (SW-C-Beschreibung) und detailliertem Verhalten (Behavioral Model).</li>\n<li>Der rote Rahmen grenzt die Aufgaben ab, die typischerweise von AUTOSAR-Authoring-Tools abgedeckt werden, von den Aufgaben des externen Coupling Tools.</li>\n<li>Fehlerhafter Bezeichner <code>Intefaces</code> im Schritt <code>Define BSW Module Intefaces</code> ist als Schreibfehler im Standarddokument zu beachten.</li>\n</ul>"}], "trans": [{"from": "FIG-1eb3bd252b994061", "to": "FIG-9b7b3e1a46933b02", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Die drei Prozessschritte innerhalb des rot hinterlegten Bereichs („Covered by AUTOSAR authoring tools“) wurden von abgerundeten Rechtecken in Chevron- bzw. Pfeilsymbole (Prozessschrittform analog zu den oberen Translationsschritten) geändert:</li>\n<li>„Define VFB Application Software Component“</li>\n<li>„Deploy Software Component“</li>\n<li>„Define BSW Module Intefaces“</li>\n<li>Die Beschriftungen dieser drei Aufgaben sind nun direkt unter bzw. außerhalb der jeweiligen Chevron-Symbole platziert statt zentriert im Kasten.</li>\n<li>Zeilenumbruch im Textblock rechts neben dem Pfeil „Translation of Behavioral Model into SW-C Description“ leicht angepasst.</li>\n</ul>"}]};
